function countSubstrings(s) {
  const empty = () => Array.from({ length: 10 }, (_, d) => new Array(d).fill(0));
  let dp = empty();
  let total = 0;
  for (const ch of s) {
    const digit = ch.charCodeAt(0) - 48;
    const next = empty();
    for (let d = 1; d <= 9; d++) {
      for (let r = 0; r < d; r++) {
        next[d][(r * 10 + digit) % d] += dp[d][r];
      }
      next[d][digit % d]++;
    }
    if (digit > 0) {
      total += next[digit][0];
    }
    dp = next;
  }
  return total;
}

