function countSubstrings(s) {
  // Check every substring directly, computing its value modulo its last digit one digit at a time.
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i; j < s.length; j++) {
      const last = Number(s[j]);
      if (last === 0) continue;
      let remainder = 0;
      for (let t = i; t <= j; t++) remainder = (remainder * 10 + Number(s[t])) % last;
      if (remainder === 0) total++;
    }
  }
  return total;
}

