function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 8000 + pick(2001) : 1 + pick(14);
  // Some strings draw from a few digits only, so zero-heavy and repetitive inputs appear too.
  const pools = ['0123456789', '0123456789', '01', '7', '048', '369', '50', '123456789', '70'];
  const pool = pools[pick(pools.length)];
  let s = '';
  for (let i = 0; i < n; i++) s += pool[pick(pool.length)];
  return [s];
}
